# Per-case simulation length.  Most cases run 520 steps.  8n M is essentially SOLVED at
# 520 (6 of 8 seeds land within ~1 step per spike, mean|dt| 2.75) -- the discriminating
# regime is the longer run, where the supervision doubles to 18 output spikes and the rare
# accumulators N3/N4 get killed instead.  So the case carries its own length.
CASE_STEPS = {"8n M": 1040, "50n A": 1040, "50n B": 1040,
               "50n C": 1040, "14n P": 1040, "14n Q": 1040}
DEFAULT_STEPS = 520


def steps_for(name):
    return CASE_STEPS.get(name, DEFAULT_STEPS)


def _job(a):
    name, seed, rounds = a
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import numpy as np, grad_trace as G
    E, N, outs, Wl = CASES[name]
    C = np.array(E, np.int32); W = np.array(Wl, np.float32)
    params = G.mkparams(520)
    T = {n: G.sp(G.fsim(C, N, W, params), n) for n in range(N)}
    w = (W * np.random.default_rng(seed).uniform(0.5, 1.5, len(W))).astype(float)
    w0 = w.copy()
    w = G.train(C, N, outs, w, T, params, rounds=rounds, lr=G.LR)
    V = G.fsim(C, N, w, params)
    return dict(seed=seed, w0=np.round(w0, 0).tolist(), w=np.round(w, 0).tolist(),
                got={n: G.sp(V, n) for n in range(N)}, true=T, outs=outs)


def main():
    name = sys.argv[1]
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 1600
    seeds = int(sys.argv[3]) if len(sys.argv) > 3 else 8
    E, N, outs, Wl = CASES[name]
    with mp.get_context("spawn").Pool(min(16, seeds)) as pool:
        res = pool.map(_job, [(name, s, rounds) for s in range(seeds)])
    print(f"===== {name}  edges={E}  true w={Wl}  rounds={rounds} =====")
    print("TRUE spikes:")
    for n in range(N):
        print(f"    N{n}: {res[0]['true'][n]}")
    print()
    for r in res:
        o = outs[0]; f = r["got"][o]; t = r["true"][o]
        if f == t:
            print(f"  seed{r['seed']}: OK    w={r['w']}")
            continue
        d = ([a - b for a, b in zip(f, t)] if len(f) == len(t)
             else f"COUNT {len(f)} vs {len(t)}")
        print(f"  seed{r['seed']}: FAIL  off={d}")
        print(f"        w0={r['w0']} -> w={r['w']}   true={Wl}")
        for n in range(N):
            mark = " <- OUT" if n == o else ""
            print(f"        N{n}: got {r['got'][n]}{mark}")


if __name__ == "__main__":
    main()
